def test_json_bulk_invalid(headers):
    """
    Test the API response when the request is invalid JSON or contains too many locations.
    """
    params = {"q": "[{'invalid':'json'}"}  # Passing malformed JSON as a string for testing purpose
    response = requests.get(f"{BASE_URL}/search.json", headers=headers, params=params)
    assert response.status_code == 400
    data = response.json()
